<?php require '../../../config/bootstrap.php';rate_limit('login',10,60);$d=request_json();$email=strtolower(trim((string)($d['email']??'')));$pw=(string)($d['password']??'');if(!filter_var($email,FILTER_VALIDATE_EMAIL)||$pw==='')json_response(['error'=>'Credenciais inválidas'],422);try{$s=db()->prepare('SELECT u.*,t.name tenant_name,t.status tenant_status FROM users u JOIN tenants t ON t.id=u.tenant_id WHERE u.email=? AND u.status="active" LIMIT 1');$s->execute([$email]);$u=$s->fetch();if(!$u||$u['tenant_status']!=='active'||!password_verify($pw,$u['password_hash'])){usleep(250000);json_response(['error'=>'Email ou palavra-passe inválidos'],401);}start_secure_session();session_regenerate_id(true);$_SESSION=['user_id'=>(int)$u['id'],'tenant_id'=>(int)$u['tenant_id'],'name'=>$u['name'],'role'=>$u['role'],'csrf'=>bin2hex(random_bytes(32))];db()->prepare('UPDATE users SET last_login_at=NOW() WHERE id=?')->execute([$u['id']]);audit(['id'=>$u['id'],'tenant_id'=>$u['tenant_id']],'login','user',(int)$u['id']);json_response(['user'=>['name'=>$u['name'],'role'=>$u['role'],'tenant'=>$u['tenant_name']],'csrf'=>$_SESSION['csrf']]);}catch(Throwable $e){log_error($e);json_response(['error'=>'Erro interno'],500);}
